Como el fixture no incluye `app/`, te dejo el provider listo para incorporar como `app/providers/smooth-scroll-provider.tsx`:

```tsx
"use client";

import { useEffect, useRef, type PropsWithChildren } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { ReactLenis, type LenisRef } from "lenis/react";

const LENIS_OPTIONS = {
  autoRaf: false,
  lerp: 0.1,
  respectReducedMotion: true,
} as const;

export function SmoothScrollProvider({
  children,
}: PropsWithChildren) {
  const lenisRef = useRef<LenisRef>(null);

  useEffect(() => {
    const lenis = lenisRef.current?.lenis;

    if (!lenis) return;

    gsap.registerPlugin(ScrollTrigger);

    const updateScrollTrigger = () => {
      ScrollTrigger.update();
    };

    const updateLenis = (time: number) => {
      // GSAP entrega segundos; Lenis espera milisegundos.
      lenis.raf(time * 1000);
    };

    lenis.on("scroll", updateScrollTrigger);
    gsap.ticker.add(updateLenis);

    // Evita saltos al regresar desde una pestaña inactiva.
    gsap.ticker.lagSmoothing(0);

    const refreshFrame = requestAnimationFrame(() => {
      ScrollTrigger.refresh();
    });

    return () => {
      cancelAnimationFrame(refreshFrame);
      lenis.off("scroll", updateScrollTrigger);
      gsap.ticker.remove(updateLenis);
    };
  }, []);

  return (
    <ReactLenis root ref={lenisRef} options={LENIS_OPTIONS}>
      {children}
    </ReactLenis>
  );
}
```

Importa el CSS global de Lenis y monta el provider en `app/layout.tsx`:

```tsx
import "lenis/dist/lenis.css";
import { SmoothScrollProvider } from "./providers/smooth-scroll-provider";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es">
      <body>
        <SmoothScrollProvider>
          {children}
        </SmoothScrollProvider>
      </body>
    </html>
  );
}
```

No requiere `scrollerProxy()` porque Lenis mantiene el scroll nativo de `window`. La integración oficial consiste en alimentar Lenis desde el ticker de GSAP, actualizar ScrollTrigger en cada evento de scroll y desactivar `lagSmoothing`. [Lenis: integración con GSAP](https://github.com/darkroomengineering/lenis#gsap-scrolltrigger), [adaptador React oficial](https://github.com/darkroomengineering/lenis/blob/main/packages/react/README.md).
